import java.util.Scanner;

public class Main {
    public static int digits(int n) {
        if (n < 10) {
            return 1;
        }
        return 1 + digits(n / 10);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        System.out.println(n + " 一共有 " + digits(n) + " 位数{tail}");
    }
}
